import Foundation
import KwipMLCore

/// Reviewed public presentation. No solver, private fixture or project state is evaluated here.
@MainActor enum AffineRemainingActivationCopy {
    struct Section {let id:String;let title:String;let text:String;let kind:LessonContentBlock.Kind}
    struct Packet {let steps:[LessonContentStep];let reference:[Section]}
    static func packet(_ identity:ModelConstructionLessonIdentity?)->Packet? {
        guard let identity else {return nil}
        switch identity.assessmentID {
        case "assessment.activation-tanh": return .init(steps:[
            LessonContent.step("goal","Meet the Tanh assessment","An activation changes values as they move through a model. Tanh can keep signed values within a smooth bounded range. Negative inputs stay negative, positive inputs stay positive, and zero stays zero. Outputs approach −1 and 1 as input magnitudes grow.\n\nIn this assessment, the canvas starts with two unconnected blocks:\n- Input receives rows with two numeric features. The checker supplies the actual numbers.\n- Result must receive Tanh applied separately to each number, with the same two features in the same order.\n\nYou will add the connecting calculation and enter its fixed parameters. The adapter requires an explicit Linear block as well as Tanh. That requirement belongs to this exercise; Tanh itself has no trainable parameters.\n\nThis is a small transformation exercise, not model training. It helps you recognize what the activation changes before using it in a larger model.",kind:.explanation),
            LessonContent.step("try.0","Build the transformation","1. Read the public examples in Task, supplied values & hints. Predict what happens to negative, zero and positive inputs.\n2. Place a Linear layer and Tanh, and connect Input through your construction to Result. Tanh must be on the connected output path; an unused block cannot perform the transformation.\n3. Select Linear and set two input features and two output features in Parameters. Initialize explicit weights and biases if needed. Choose values that preserve the required transformation rather than mix features or shift the input unexpectedly.\n4. Tanh has no settings or learned numbers. Keep each value independent, preserve feature order and finish pending numeric edits.\n5. Choose Submit assessment in the rail when the connected calculation is ready.\n\nThe checker evaluates your entered calculation on additional values. It does not learn the Linear weights for you. Equivalent constructions can pass when they preserve the task's required behavior.",kind:.canvasAction),
            LessonContent.step("inspect","Submit and interpret the result","Read Assessment feedback after Submit assessment finishes. Negative inputs stay negative, positive inputs stay positive, and zero stays zero. Outputs approach −1 and 1 as input magnitudes grow.\n\n- Compare a failure with the expected behavior, then inspect connection order, feature widths, Linear weights and biases.\n- Changing a neighboring value or another observation must not change the transformation of an unchanged value.\n- If checking cannot start or is cancelled, resolve that condition before treating it as evidence about the mathematics.\n\nCompletion requires a passing result with its receipt saved. After editing, submit again: an earlier result belongs to the earlier construction. Saving keeps your attempt; it does not demonstrate correctness.",kind:.observation)
        ],reference:[
            .init(id:"reference.goal",title:"The required behavior",text:"Apply Tanh independently to each incoming number. Negative inputs stay negative, positive inputs stay positive, and zero stays zero. Outputs approach −1 and 1 as input magnitudes grow.\n\nPreserve two features per observation and their order. Include Tanh on the connected path and the explicit Linear parameters required by the adapter.",kind:.explanation),
            .init(id:"reference.workflow",title:"Work on the canvas",text:"Drag allowed components onto the canvas and connect their ports from Input to Result. Select each Linear layer to edit its widths, Weight matrix and Bias in Parameters.\n\nThis Construction uses Submit assessment. It does not run an ordinary training flow or find the parameters for you.",kind:.canvasAction),
            .init(id:"reference.examples",title:"Read the public examples",text:"These illustrative rows describe the rule; they are not captured results from your graph. Rounded values are shown for readability.\n\n- [−2, 0] gives approximately [−0.964028, 0].\n- [1, 2] gives approximately [0.761594, 0.964028].\n\nRead each feature separately. The displayed decimal values are rounded for readability; compare the checker outcome rather than entering these rounded examples as a fixed answer.",kind:.visual),
            .init(id:"reference.configure",title:"Configure the Linear scaffold",text:"The adapter requires a Linear layer with explicit parameters. A layer that leaves each feature unchanged is a useful scaffold before Tanh.\n\nEach weight-table row produces an output feature; each column receives an input feature. Indices begin at 0. Work out which entries preserve a feature, which would mix in its neighbor, and which offsets would shift the input. Finish edits before submitting.",kind:.canvasAction),
            .init(id:"reference.inspect",title:"Reason about the response",text:"These are signed responses, not probabilities. Applying Tanh twice usually changes the result; unlike ReLU, it is not generally safe to repeat it without changing the calculation.\n\nTanh acts on each value separately. It does not compare features, choose a winning class or normalize a batch. Use the checker feedback to distinguish a wrong transformation from an unavailable or cancelled check.",kind:.observation),
            .init(id:"reference.criteria",title:"What completion means",text:"The checker compares your connected Tanh calculation on independent inputs, including negative, zero and positive values. Preserve rows, two features and their order.\n\nA passing assessment with its receipt saved counts toward this task. Reading or saving an unfinished graph does not. Existing exact criteria and resource limits remain in Optional · exact checks and limits.",kind:.observation),
            .init(id:"reference.notation",title:"Optional · understand the curve",text:"tanh(x) = (exp(x) − exp(−x)) / (exp(x) + exp(−x))\n\nTanh is short for hyperbolic tangent. exp is the exponential function. Saturation means the output changes very little near either end. Reversing the input sign reverses the output sign. Its small-change sensitivity is 1 − y², where y is the output. This optional relationship is not a separate gradient-construction task.\n\nTanh is not a general repair for unstable training. Its usefulness depends on the model and the task.",kind:.detail)
        ])
        case "assessment.activation-sigmoid": return .init(steps:[
            LessonContent.step("goal","Meet the Sigmoid assessment","An activation changes values as they move through a model. Sigmoid can turn each signed input into a smooth response between zero and one. Negative inputs produce values below one half, zero produces one half, and positive inputs produce values above one half. Large magnitudes approach the ends of the range.\n\nIn this assessment, the canvas starts with two unconnected blocks:\n- Input receives rows with two numeric features. The checker supplies the actual numbers.\n- Result must receive Sigmoid applied separately to each number, with the same two features in the same order.\n\nYou will add the connecting calculation and enter its fixed parameters. The adapter requires an explicit Linear block as well as Sigmoid. That requirement belongs to this exercise; Sigmoid itself has no trainable parameters.\n\nThis is a small transformation exercise, not model training. It helps you recognize what the activation changes before using it in a larger model.",kind:.explanation),
            LessonContent.step("try.0","Build the transformation","1. Read the public examples in Task, supplied values & hints. Predict what happens to negative, zero and positive inputs.\n2. Place a Linear layer and Sigmoid, and connect Input through your construction to Result. Sigmoid must be on the connected output path; an unused block cannot perform the transformation.\n3. Select Linear and set two input features and two output features in Parameters. Initialize explicit weights and biases if needed. Choose values that preserve the required transformation rather than mix features or shift the input unexpectedly.\n4. Sigmoid has no settings or learned numbers. Keep each value independent, preserve feature order and finish pending numeric edits.\n5. Choose Submit assessment in the rail when the connected calculation is ready.\n\nThe checker evaluates your entered calculation on additional values. It does not learn the Linear weights for you. Equivalent constructions can pass when they preserve the task's required behavior.",kind:.canvasAction),
            LessonContent.step("inspect","Submit and interpret the result","Read Assessment feedback after Submit assessment finishes. Negative inputs produce values below one half, zero produces one half, and positive inputs produce values above one half. Large magnitudes approach the ends of the range.\n\n- Compare a failure with the expected behavior, then inspect connection order, feature widths, Linear weights and biases.\n- Changing a neighboring value or another observation must not change the transformation of an unchanged value.\n- If checking cannot start or is cancelled, resolve that condition before treating it as evidence about the mathematics.\n\nCompletion requires a passing result with its receipt saved. After editing, submit again: an earlier result belongs to the earlier construction. Saving keeps your attempt; it does not demonstrate correctness.",kind:.observation)
        ],reference:[
            .init(id:"reference.goal",title:"The required behavior",text:"Apply Sigmoid independently to each incoming number. Negative inputs produce values below one half, zero produces one half, and positive inputs produce values above one half. Large magnitudes approach the ends of the range.\n\nPreserve two features per observation and their order. Include Sigmoid on the connected path and the explicit Linear parameters required by the adapter.",kind:.explanation),
            .init(id:"reference.workflow",title:"Work on the canvas",text:"Drag allowed components onto the canvas and connect their ports from Input to Result. Select each Linear layer to edit its widths, Weight matrix and Bias in Parameters.\n\nThis Construction uses Submit assessment. It does not run an ordinary training flow or find the parameters for you.",kind:.canvasAction),
            .init(id:"reference.examples",title:"Read the public examples",text:"These illustrative rows describe the rule; they are not captured results from your graph. Rounded values are shown for readability.\n\n- [−2, 0] gives approximately [0.119203, 0.500000].\n- [1, 2] gives approximately [0.731059, 0.880797].\n\nRead each feature separately. The displayed decimal values are rounded for readability; compare the checker outcome rather than entering these rounded examples as a fixed answer.",kind:.visual),
            .init(id:"reference.configure",title:"Configure the Linear scaffold",text:"The adapter requires a Linear layer with explicit parameters. A layer that leaves each feature unchanged is a useful scaffold before Sigmoid.\n\nEach weight-table row produces an output feature; each column receives an input feature. Indices begin at 0. Work out which entries preserve a feature, which would mix in its neighbor, and which offsets would shift the input. Finish edits before submitting.",kind:.canvasAction),
            .init(id:"reference.inspect",title:"Reason about the response",text:"Sigmoid does not make the values in a row add to one. Its outputs are not automatically calibrated probabilities: a value of 0.8 is not evidence of an 80% chance without a suitable model, training objective and evaluation.\n\nSigmoid acts on each value separately. It does not compare features, choose a winning class or normalize a batch. Use the checker feedback to distinguish a wrong transformation from an unavailable or cancelled check.",kind:.observation),
            .init(id:"reference.criteria",title:"What completion means",text:"The checker compares your connected Sigmoid calculation on independent inputs, including negative, zero and positive values. Preserve rows, two features and their order.\n\nA passing assessment with its receipt saved counts toward this task. Reading or saving an unfinished graph does not. Existing exact criteria and resource limits remain in Optional · exact checks and limits.",kind:.observation),
            .init(id:"reference.notation",title:"Optional · understand the curve",text:"s(x) = 1 / (1 + exp(−x))\n\nx is one input value and exp is the exponential function. Saturation means the output changes very little near zero or one. Its small-change sensitivity is s(x) × (1 − s(x)), largest at input zero. This optional relationship explains the curve; this assessment checks forward values, not a gradient construction.\n\nSigmoid is not a general repair for unstable training. Its usefulness depends on the model and the task.",kind:.detail)
        ])
        case "assessment.activation-gelu-exact": return .init(steps:[
            LessonContent.step("goal","Meet exact GELU","GELU is an activation that smoothly gates each value: it keeps much of a large positive value and reduces a negative value without simply clipping it to zero. This kind of transformation appears in many Transformer models. Here you will isolate the rule before using it in a larger architecture.\n\nThis task requires exact GELU. The exact formula uses the error function, erf. The app supplies that calculation through GELU; you do not need to implement erf yourself.\n\nThe canvas starts with unconnected Input and Result blocks. Each input row has two numeric features; Result must receive the transformed values in their original positions.\n\nAdd the connecting layers. The adapter requires explicit Linear parameters and at least one GELU. In each GELU block, choose Exact in the Approximation selector. The checker evaluates the calculation; it does not train a model.",kind:.explanation),
            LessonContent.step("try.0","Build and configure the gate","1. Add Linear and GELU from the allowed components. Connect Input through your calculation to Result, keeping two features at each boundary.\n2. Select the GELU block and set Approximation to Exact. Check every GELU in the construction: this assessment requires the same declared mode for all of them.\n3. Select Linear and use Parameters to set its input/output widths, Weight matrix and Bias. Initialize explicit values if needed. A layer that leaves each feature unchanged is a useful scaffold; equivalent arrangements can also pass.\n4. Predict the response to zero, a small negative value and a large positive value. Preserve each value independently; do not swap columns or mix observations.\n5. Finish numeric edits, then choose Submit assessment in the rail.\n\nGELU has no learned numbers of its own. The Linear scaffold is a requirement of this lesson's adapter, not a mathematical requirement for using GELU in a model.",kind:.canvasAction),
            LessonContent.step("inspect","Submit and interpret the result","Read Assessment feedback when the check finishes. Zero should remain zero; small negative inputs can remain negative, and large positive inputs pass through almost unchanged.\n\n- A failed comparison can come from the wrong approximation mode, surrounding Linear parameters or connections.\n- ReLU clips negatives to zero; Tanh alone bounds values in another way. Neither substitutes for GELU.\n- If checking cannot start or is cancelled, resolve that condition before interpreting it as mathematical failure.\n\nCompletion requires a passing assessment with its receipt saved. Submit again after edits. A saved attempt or an earlier passing result does not certify the edited construction.",kind:.observation)
        ],reference:[
            .init(id:"reference.goal",title:"The required behavior",text:"Apply exact GELU to each number independently. Preserve two features per row, their order and the number of observations. In each GELU block, choose Exact in the Approximation selector.",kind:.explanation),
            .init(id:"reference.workflow",title:"Work on the canvas",text:"Connect the allowed components from Input to Result. Select Linear to set its explicit widths and parameters, and select GELU to check its Approximation selection.\n\nFinish pending fields before using Submit assessment. The checker evaluates your fixed construction rather than optimizing it.",kind:.canvasAction),
            .init(id:"reference.examples",title:"Predict the gated values",text:"These are qualitative expectations, not captured values or private checker examples:\n- Zero remains zero.\n- A small negative input can produce a negative output with reduced magnitude.\n- A large positive input is kept almost unchanged.\n\nA smooth gate differs from ReLU clipping. Applying GELU repeatedly generally changes the calculation; matching its name or appearance is not sufficient.",kind:.visual),
            .init(id:"reference.configure",title:"Configure the declared mode",text:"Approximation must be Exact on every GELU block for this task. The exact task uses erf. A tanh approximation is a different declared mode even when many values look close.\n\nThe adapter also requires a Linear layer with explicit weights and biases. Keep its feature mapping and offsets consistent with the required GELU behavior. Rows in its weight table produce outputs; columns receive inputs.",kind:.canvasAction),
            .init(id:"reference.inspect",title:"Separate the rule from training",text:"The checker tests forward values. It does not ask you to build a backward gradient graph or demonstrate that a larger model trains well.\n\nGELU operates on one value at a time. Changing a neighboring feature must not change its response. Different connected arrangements may pass when they implement the declared mode.",kind:.observation),
            .init(id:"reference.criteria",title:"What completion means",text:"The assessment compares the exact GELU calculation on independent values, including values that distinguish approximation modes. Preserve rows, shape and feature order, and satisfy the adapter's component and explicit-parameter requirements.\n\nCompletion requires a passing assessment with its receipt saved. Exact criteria and resource limits remain available in Optional · exact checks and limits.",kind:.observation),
            .init(id:"reference.notation",title:"Optional · understand the gate",text:"GELU(x) = 0.5 x (1 + erf(x/√2))\n\nx is one input number. erf is the error function; tanh is a smooth curve between −1 and 1. √ means square root, π is pi and x³ means x multiplied by itself three times. The gate multiplies x; it is not Tanh by itself.\n\nA gradient describes sensitivity to a small change. Near zero, GELU passes about half of a small change. Large positive inputs pass nearly all of it; far-negative inputs change their output very little. In some negative regions, increasing the input can make the output briefly more negative. This is optional context, not an additional gradient-construction assessment.",kind:.detail)
        ])
        case "assessment.activation-gelu-tanh": return .init(steps:[
            LessonContent.step("goal","Meet tanh-approximate GELU","GELU is an activation that smoothly gates each value: it keeps much of a large positive value and reduces a negative value without simply clipping it to zero. This kind of transformation appears in many Transformer models. Here you will isolate the rule before using it in a larger architecture.\n\nThis task requires tanh-approximate GELU. The tanh formula approximates the exact Gaussian gate. It is still GELU; placing Tanh by itself performs a different calculation.\n\nThe canvas starts with unconnected Input and Result blocks. Each input row has two numeric features; Result must receive the transformed values in their original positions.\n\nAdd the connecting layers. The adapter requires explicit Linear parameters and at least one GELU. In each GELU block, choose Tanh approximation in the Approximation selector. The checker evaluates the calculation; it does not train a model.",kind:.explanation),
            LessonContent.step("try.0","Build and configure the gate","1. Add Linear and GELU from the allowed components. Connect Input through your calculation to Result, keeping two features at each boundary.\n2. Select the GELU block and choose Tanh approximation in Approximation. Check every GELU in the construction: this assessment requires the same declared mode for all of them.\n3. Select Linear and use Parameters to set its input/output widths, Weight matrix and Bias. Initialize explicit values if needed. A layer that leaves each feature unchanged is a useful scaffold; equivalent arrangements can also pass.\n4. Predict the response to zero, a small negative value and a large positive value. Preserve each value independently; do not swap columns or mix observations.\n5. Finish numeric edits, then choose Submit assessment in the rail.\n\nGELU has no learned numbers of its own. The Linear scaffold is a requirement of this lesson's adapter, not a mathematical requirement for using GELU in a model.",kind:.canvasAction),
            LessonContent.step("inspect","Submit and interpret the result","Read Assessment feedback when the check finishes. Zero should remain zero; small negative inputs can remain negative, and large positive inputs pass through almost unchanged.\n\n- A failed comparison can come from the wrong approximation mode, surrounding Linear parameters or connections.\n- ReLU clips negatives to zero; Tanh alone bounds values in another way. Neither substitutes for GELU.\n- If checking cannot start or is cancelled, resolve that condition before interpreting it as mathematical failure.\n\nCompletion requires a passing assessment with its receipt saved. Submit again after edits. A saved attempt or an earlier passing result does not certify the edited construction.",kind:.observation)
        ],reference:[
            .init(id:"reference.goal",title:"The required behavior",text:"Apply tanh-approximate GELU to each number independently. Preserve two features per row, their order and the number of observations. In each GELU block, choose Tanh approximation in the Approximation selector.",kind:.explanation),
            .init(id:"reference.workflow",title:"Work on the canvas",text:"Connect the allowed components from Input to Result. Select Linear to set its explicit widths and parameters, and select GELU to check its Approximation selection.\n\nFinish pending fields before using Submit assessment. The checker evaluates your fixed construction rather than optimizing it.",kind:.canvasAction),
            .init(id:"reference.examples",title:"Predict the gated values",text:"These are qualitative expectations, not captured values or private checker examples:\n- Zero remains zero.\n- A small negative input can produce a negative output with reduced magnitude.\n- A large positive input is kept almost unchanged.\n\nA smooth gate differs from ReLU clipping. Applying GELU repeatedly generally changes the calculation; matching its name or appearance is not sufficient.",kind:.visual),
            .init(id:"reference.configure",title:"Configure the declared mode",text:"Approximation must be Tanh approximation on every GELU block for this task. This formula approximates the exact Gaussian calculation. Small differences are expected; the assessment checks the requested approximate function.\n\nThe adapter also requires a Linear layer with explicit weights and biases. Keep its feature mapping and offsets consistent with the required GELU behavior. Rows in its weight table produce outputs; columns receive inputs.",kind:.canvasAction),
            .init(id:"reference.inspect",title:"Separate the rule from training",text:"The checker tests forward values. It does not ask you to build a backward gradient graph or demonstrate that a larger model trains well.\n\nGELU operates on one value at a time. Changing a neighboring feature must not change its response. Different connected arrangements may pass when they implement the declared mode.",kind:.observation),
            .init(id:"reference.criteria",title:"What completion means",text:"The assessment compares the tanh-approximate GELU calculation on independent values, including values that distinguish approximation modes. Preserve rows, shape and feature order, and satisfy the adapter's component and explicit-parameter requirements.\n\nCompletion requires a passing assessment with its receipt saved. Exact criteria and resource limits remain available in Optional · exact checks and limits.",kind:.observation),
            .init(id:"reference.notation",title:"Optional · understand the gate",text:"GELU(x) ≈ 0.5 x (1 + tanh(√(2/π) (x + 0.044715 x³)))\n\nx is one input number. erf is the error function; tanh is a smooth curve between −1 and 1. √ means square root, π is pi and x³ means x multiplied by itself three times. The gate multiplies x; it is not Tanh by itself.\n\nA gradient describes sensitivity to a small change. Near zero, GELU passes about half of a small change. Large positive inputs pass nearly all of it; far-negative inputs change their output very little. In some negative regions, increasing the input can make the output briefly more negative. This is optional context, not an additional gradient-construction assessment.",kind:.detail)
        ])
        default:return nil
        }
    }
}
